$ErrorActionPreference = "Stop"

# ============================================================
# CONFIG
# ============================================================

$MainDir            = "C:\Windows\System32\Acceleron"
$BaseDir            = Join-Path $MainDir "Applocker"
$CertDir            = Join-Path $MainDir "Certificate"

$AppLockerPath      = Join-Path $BaseDir "AppLocker.exe"
$WatchDogPath       = Join-Path $BaseDir "runtimesvc.exe"
$JsonPath           = Join-Path $BaseDir "policy.json"
$CertPath           = Join-Path $CertDir "AcceleronCertificate.cer"

$RegPath            = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\AppLocker"

# Calculate folder size in KB
$EstimatedSize = [math]::Ceiling(((Get-ChildItem $BaseDir -Recurse -File | Measure-Object Length -Sum).Sum) / 1KB)

$UninstallCmd = 'powershell.exe -ExecutionPolicy Bypass -NoProfile -Command "$ErrorActionPreference = ''SilentlyContinue''; Get-Process -Name applocker,runtimesvc -ErrorAction SilentlyContinue | Stop-Process -Force; Start-Sleep -Seconds 2; Remove-Item -LiteralPath ''C:\Windows\System32\Acceleron\Applocker'' -Recurse -Force -ErrorAction SilentlyContinue; Remove-ItemProperty -LiteralPath ''HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run'' -Name ''AppLockerWatchdog'' -ErrorAction SilentlyContinue; Remove-Item -LiteralPath ''HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\AppLocker'' -Recurse -Force -ErrorAction SilentlyContinue"'

$PinnedThumbprint   = "C9C559D901C9B31C90AF64D0D20A091013A3D4C3"

$IsSystem           = ([Security.Principal.WindowsIdentity]::GetCurrent().IsSystem)
$IsAdmin            = ([Security.Principal.WindowsPrincipal] `
                      [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)

# ============================================================
# ENSURE BASE DIRECTORY
# ============================================================

# Create base directory if not exists
if (-not (Test-Path $BaseDir)) {
    New-Item -Path $BaseDir -ItemType Directory -Force | Out-Null
}

# Create certificate directory if not exists
if (-not (Test-Path $CertDir)) {
    New-Item -Path $CertDir -ItemType Directory -Force | Out-Null
}

# ============================================================
# CLEAN OLD TASKS (SAFE)
# ============================================================
Get-Process -Name applocker,runtimesvc -ErrorAction SilentlyContinue | Stop-Process -Force
Stop-Service -Name AppIDSvc -Force -ErrorAction SilentlyContinue
Set-Service -Name AppIDSvc -StartupType Disabled -ErrorAction SilentlyContinue
Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\AppIDSvc" -Name "Start" -Value 4 -ErrorAction SilentlyContinue
Remove-Item $AppLockerPath, $WatchDogPath, $CertPath -Force -ErrorAction SilentlyContinue

